import json
from pathlib import Path
from datetime import datetime, timezone, timedelta
TZ=timezone(timedelta(hours=8))

def extract_text(o):
  msg=o.get('message') or {}
  c=msg.get('content')
  if isinstance(c,list):
    parts=[]
    for it in c:
      if isinstance(it,dict) and it.get('type')=='text':
        parts.append(it.get('text') or '')
    return '\n'.join(parts)
  if isinstance(c,str): return c
  return ''

root=Path('/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts')
# today's dirs by mtime
cands=[]
for d in root.iterdir():
  if not d.is_dir(): continue
  for p in d.glob('*.jsonl'):
    m=datetime.fromtimestamp(p.stat().st_mtime,tz=TZ)
    if m.date().isoformat()=='2026-11-10':
      cands.append(p)
# also new-mac mirror
nm=Path('/Users/mac/.dc-platform/memory/mirrors/agent-transcripts/new-mac')
for d in nm.iterdir() if nm.exists() else []:
  for p in d.glob('*.jsonl'):
    m=datetime.fromtimestamp(p.stat().st_mtime,tz=TZ)
    if m.date().isoformat()=='2026-11-10':
      cands.append(p)

print('candidates', len(cands))
for p in sorted(cands, key=lambda x:x.stat().st_mtime):
  users=[]; lasts=[]
  with p.open() as f:
    for line in f:
      try:o=json.loads(line)
      except: continue
      t=extract_text(o)
      if not t: continue
      if o.get('role')=='user':
        # strip tags roughly
        u=t
        if '<user_query>' in u:
          u=u.split('<user_query>',1)[1].split('</user_query>',1)[0]
        users.append(' '.join(u.split())[:240])
      elif o.get('role')=='assistant' and not t.startswith('[REDACTED]') and 'tool_use' not in t:
        lasts.append(' '.join(t.split())[:240])
  print('\n====', p.parent.name[:12], datetime.fromtimestamp(p.stat().st_mtime,tz=TZ).strftime('%H:%M'), 'U',len(users),'A',len(lasts))
  for i,u in enumerate(users[:2]):
    print(f'U{i}:', u)
  if lasts:
    print('A:', lasts[-1])
